        u={'range':0,'exact':0}
        for i in res:u[models[i]['spec']['mode']]+=models[i]['entries']
        return u
    def commit(fid,flow,at,reason,pat=None):
        model=models[flow['release']]
        if pat is None:
            prefix=flow['values'][:model['spec']['width']]
            prefix += [1514]*(model['spec']['width']-len(prefix))
            node=model['backup'][0]
            while len(node)>1:
                feature,threshold,left,right=node
                node=model['backup'][left if 2*prefix[feature]<=threshold else right]
            label=node[0];rule=start=None
        else:label=pat['class'];rule=pat['id'];start=len(flow['values'])-len(pat['range'])
        decisions.append(dict(flow=fid,epoch=flow['epoch'],release=flow['release'],at=at,seen=len(flow['values']),reason=reason,**{'class':label,'rule':rule,'start':start}))
        flow['done']=True
    for at,event in enumerate(e for b in blocks for e in b):
